def glyph(font, ch):
    """Return (advance, width, height, y-offset, hex) for a char."""
    g = font.get(ch)
    if g is None:
        g = font.get("?", (8, 0, 0, 0, ""))
    return g


def text_width(font, text, track=0):
    total = 0
    for ch in text:
        total += glyph(font, ch)[0] + track
    if text:
        total -= track
    return total


def wrap_text(font, text, max_w, track=0):
    """Greedy word wrap; returns a list of lines that fit max_w."""
    lines = []
    for para in text.split("\n"):
        words = para.split(" ")
        cur = ""
        for word in words:
            trial = word if not cur else cur + " " + word
            if text_width(font, trial, track) <= max_w or not cur:
                cur = trial
            else:
                lines.append(cur)
                cur = word
        if cur or not lines:
            lines.append(cur)
    return lines


class Canvas:
    def __init__(self, w, h, bg):
        self.w = w
        self.h = h
        self.buf = bytearray(bg * (w * h))

    def _idx(self, x, y):
        return (y * self.w + x) * 3

    def set_px(self, x, y, colour):
        if 0 <= x < self.w and 0 <= y < self.h:
            i = self._idx(x, y)
            self.buf[i:i + 3] = bytes(colour)

    def blend_px(self, x, y, colour, cover):
        """Blend colour over the pixel; cover is 0..15."""
        if cover <= 0 or not (0 <= x < self.w and 0 <= y < self.h):
            return
        if cover >= 15:
            self.set_px(x, y, colour)
            return
        i = self._idx(x, y)
        b = self.buf
        for k in range(3):
            b[i + k] = (b[i + k] * (15 - cover) + colour[k] * cover) // 15

    def fill_rect(self, x, y, w, h, colour):
        x0 = max(0, x)
        y0 = max(0, y)
        x1 = min(self.w, x + w)
        y1 = min(self.h, y + h)
        if x1 <= x0 or y1 <= y0:
            return
        row = bytes(colour) * (x1 - x0)
        for yy in range(y0, y1):
            i = self._idx(x0, yy)
            self.buf[i:i + len(row)] = row

    def rect(self, x, y, w, h, colour, lw=1):
        self.fill_rect(x, y, w, lw, colour)
        self.fill_rect(x, y + h - lw, w, lw, colour)
        self.fill_rect(x, y, lw, h, colour)
        self.fill_rect(x + w - lw, y, lw, h, colour)

    def hline(self, x, y, w, colour, lw=1):
        self.fill_rect(x, y, w, lw, colour)

    def vline(self, x, y, h, colour, lw=1):
        self.fill_rect(x, y, lw, h, colour)

    def line(self, x0, y0, x1, y1, colour, lw=1):
        dx = abs(x1 - x0)
        dy = abs(y1 - y0)
        sx = 1 if x0 < x1 else -1
        sy = 1 if y0 < y1 else -1
        err = dx - dy
        x, y = x0, y0
        while True:
            self.fill_rect(x - lw // 2, y - lw // 2, lw, lw, colour)
            if x == x1 and y == y1:
                break
            e2 = 2 * err
            if e2 > -dy:
                err -= dy
                x += sx
            if e2 < dx:
                err += dx
                y += sy

    def circle(self, cx, cy, r, colour):
        for yy in range(cy - r, cy + r + 1):
            dy = yy - cy
            span = int((r * r - dy * dy) ** 0.5)
            self.fill_rect(cx - span, yy, span * 2 + 1, 1, colour)

    def ring(self, cx, cy, r, colour, lw=1):
        for yy in range(cy - r, cy + r + 1):
            dy = yy - cy
            outer = int((r * r - dy * dy) ** 0.5)
            inner_r = r - lw
            if abs(dy) < inner_r:
                inner = int((inner_r * inner_r - dy * dy) ** 0.5)
                self.fill_rect(cx - outer, yy, outer - inner, 1, colour)
                self.fill_rect(cx + inner + 1, yy, outer - inner, 1, colour)
            else:
                self.fill_rect(cx - outer, yy, outer * 2 + 1, 1, colour)

    def polygon(self, pts, colour):
        """Even-odd scanline fill of a polygon given as [(x, y), ...]."""
        if len(pts) < 3:
            return
        ys = [p[1] for p in pts]
        y0, y1 = max(0, min(ys)), min(self.h - 1, max(ys))
        n = len(pts)
        for y in range(y0, y1 + 1):
            xs = []
            for i in range(n):
                x0, yy0 = pts[i]
                x1, yy1 = pts[(i + 1) % n]
                if (yy0 <= y < yy1) or (yy1 <= y < yy0):
                    t = (y - yy0) / (yy1 - yy0)
                    xs.append(x0 + t * (x1 - x0))
            xs.sort()
            for j in range(0, len(xs) - 1, 2):
                xa = int(xs[j] + 0.5)
                xb = int(xs[j + 1] + 0.5)
                if xb >= xa:
                    self.fill_rect(xa, y, xb - xa + 1, 1, colour)

    def blit_glyph(self, x, y, font, ch, colour):
        adv, w, h, off, hexs = glyph(font, ch)
        if w == 0 or h == 0:
            return
        top = y + off
        # One hex digit per pixel, in row-major order.
        pos = 0
        for row in range(h):
            for col in range(w):
                cov = int(hexs[pos], 16)
                pos += 1
                if cov:
                    self.blend_px(x + col, top + row, colour, cov)

    def text(self, x, y_baseline, font, s, colour, track=0, align="left"):
        """Draw text with its baseline at y_baseline. Returns end x."""
        if align == "center":
            x -= text_width(font, s, track) // 2
        elif align == "right":
            x -= text_width(font, s, track)
        cx = x
        for ch in s:
            adv = glyph(font, ch)[0]
            self.blit_glyph(cx, y_baseline, font, ch, colour)
            cx += adv + track
        return cx

    def text_block(self, x, y_top, font, lines, colour, leading, track=0):
        """Draw pre-wrapped lines starting at y_top (first baseline)."""
        y = y_top
        for ln in lines:
            self.text(x, y, font, ln, colour, track=track)
            y += leading
        return y


def write_png(canvas, path):
    """Encode the canvas as a PNG with per-row adaptive filtering."""
    w, h = canvas.w, canvas.h
    raw = bytearray()
    prev = bytes(w * 3)
    buf = canvas.buf
    for y in range(h):
        row = bytes(buf[y * w * 3:(y + 1) * w * 3])
        best = None
        best_data = None
        for f in (0, 1, 2, 4):
            if f == 0:
                data = row
            elif f == 1:
                # Sub: predictor is the ORIGINAL byte 3 back, not the
                # already-filtered one, so build from row, not in place.
                data = bytes((row[i] - row[i - 3]) & 255 if i >= 3 else row[i]
                             for i in range(len(row)))
            elif f == 2:
                data = bytes((row[i] - prev[i]) & 255 for i in range(len(row)))
            else:
                data = bytearray(len(row))
                for i in range(len(row)):
                    a = row[i - 3] if i >= 3 else 0
                    b = prev[i]
                    c = prev[i - 3] if i >= 3 else 0
                    p = a + b - c
                    pa, pb, pc = abs(p - a), abs(p - b), abs(p - c)
                    pr = a if (pa <= pb and pa <= pc) else (b if pb <= pc else c)
                    data[i] = (row[i] - pr) & 255
                data = bytes(data)
            comp = zlib.compress(bytes([f]) + data, 1)
            if best is None or len(comp) < best:
                best = len(comp)
                best_data = bytes([f]) + data
        raw += best_data
        prev = row
    comp = zlib.compress(bytes(raw), 9)

    def chunk(tag, data):
        c = struct.pack(">I", len(data)) + tag + data
        return c + struct.pack(">I", zlib.crc32(tag + data) & 0xFFFFFFFF)

    ihdr = struct.pack(">IIBBBBB", w, h, 8, 2, 0, 0, 0)
    png = b"\x89PNG\r\n\x1a\n"
    png += chunk(b"IHDR", ihdr)
    png += chunk(b"IDAT", comp)
    png += chunk(b"IEND", b"")
    with open(path, "wb") as fh:
        fh.write(png)
    return len(png)


