def draw_visual(c, kind, x, y, w, h):
    if kind == "nato":
        c.fill_rect(x, y, w, h, (198, 222, 235))
        c.fill_rect(x, y + h - 26, w, 26, (120, 150, 120))
        c.fill_rect(x + w // 2 - 46, y + 8, 92, h - 34, NAVY)
        c.fill_rect(x + w // 2 - 46, y + 8, 92, 6, GOLD)
        for i in range(5):
            fx = x + w // 2 - 36 + i * 18
            c.fill_rect(fx, y + 16, 12, 16, WHITE)
            c.fill_rect(fx, y + 16, 12, 5, (0, 51, 153) if i % 2 == 0 else RED)
        c.circle(x + w - 26, y + 18, 10, GOLD)
        c.circle(x + w - 26, y + 18, 5, WHITE)
    elif kind == "talks":
        c.fill_rect(x, y, w, h, (232, 220, 196))
        c.fill_rect(x + 14, y + h - 34, w - 28, 8, (122, 84, 52))
        c.fill_rect(x + 20, y + h - 26, 6, 26, (122, 84, 52))
        c.fill_rect(x + w - 26, y + h - 26, 6, 26, (122, 84, 52))
        c.fill_rect(x + w // 2 - 30, y + 2, 60, 16, WHITE)
        c.fill_rect(x + w // 2 - 30, y + 2, 60, 3, RED)
        c.circle(x + w // 2 - 52, y + 20, 9, (139, 35, 65))
        c.circle(x + w // 2 + 52, y + 20, 9, (178, 34, 34))
        c.fill_rect(x + w // 2 - 2, y + 12, 4, 22, INK)
        c.circle(x + w // 2, y + 10, 5, GOLD)
    elif kind == "cop":
        c.fill_rect(x, y, w, h, (188, 222, 208))
        c.circle(x + w // 2, y + h // 2 + 2, 20, (70, 130, 90))
        c.polygon([(x + w // 2 - 16, y + h // 2 - 4), (x + w // 2 - 4, y + h // 2 - 12),
                   (x + w // 2 + 4, y + h // 2 - 2), (x + w // 2 - 10, y + h // 2 + 8)],
                  (120, 170, 90))
        c.polygon([(x + w // 2 + 4, y + h // 2 + 8), (x + w // 2 + 14, y + h // 2 + 2),
                   (x + w // 2 + 16, y + h // 2 + 12), (x + w // 2 + 6, y + h // 2 + 16)],
                  (120, 170, 90))
        c.circle(x + w - 24, y + 14, 9, (230, 120, 40))
        c.fill_rect(x + 8, y + h - 10, w - 16, 4, RED)
        c.line(x + 12, y + h - 18, x + w - 14, y + h - 24, RED, 2)
    elif kind == "kyiv":
        c.fill_rect(x, y, w, h, (38, 52, 74))
        c.fill_rect(x + 10, y + 12, 34, h - 12, (16, 22, 34))
        c.fill_rect(x + 48, y + 20, 30, h - 20, (16, 22, 34))
        c.fill_rect(x + 82, y + 6, 30, h - 6, (16, 22, 34))
        for wx, wy in ((18, 18), (56, 26), (90, 12), (26, 26), (98, 20)):
            c.fill_rect(x + wx, y + wy, 7, 8, (240, 200, 90))
        c.circle(x + w - 30, y + 16, 10, (240, 120, 30))
        c.circle(x + w - 42, y + 10, 6, (200, 200, 200))
        c.circle(x + w - 18, y + 8, 4, (220, 220, 220))
        c.fill_rect(x, y + h - 5, w, 5, (90, 80, 70))
    elif kind == "cricket":
        c.fill_rect(x, y, w, h, (140, 190, 120))
        c.fill_rect(x + w // 2 - 26, y + 6, 52, h - 12, (214, 186, 130))
        for i in range(3):
            c.fill_rect(x + w // 2 - 12 + i * 9, y + 10, 4, 18, (240, 220, 160))
        c.circle(x + w // 2 + 34, y + h - 20, 7, RED)
        c.line(x + w // 2 - 34, y + h - 12, x + w // 2 - 6, y + 22, (150, 110, 60), 5)
        c.fill_rect(x + 8, y + h - 10, w - 16, 4, WHITE)
    elif kind == "report":
        c.fill_rect(x, y, w, h, (222, 214, 196))
        c.fill_rect(x + w // 2 - 30, y + 4, 60, h - 8, WHITE)
        c.rect(x + w // 2 - 30, y + 4, 60, h - 8, INK, 1)
        for i in range(3):
            c.fill_rect(x + w // 2 - 22, y + 12 + i * 7, 34, 2, (150, 150, 145))
        c.fill_rect(x + w // 2 - 22, y + 12, 20, 2, RED)
        c.circle(x + w - 24, y + h - 14, 9, (255, 255, 255))
        c.ring(x + w - 24, y + h - 14, 9, INK, 2)
        c.line(x + w - 17, y + h - 7, x + w - 9, y + h - 1, INK, 2)
    elif kind == "taiwan":
        c.fill_rect(x, y, w, h, WHITE)
        for gx in range(0, w, 14):
            c.vline(x + gx, y + 4, h - 8, LIGHTGREY, 1)
